window.VO = [{"id":"a1","scene":"surface","text":"This is the button that lets your customers connect their own domain.","t0":1.0417,"t1":5.0517,"beat0":1.25,"beat1":6.062},{"id":"a2","scene":"surface","text":"It looks small. That's the part above the water.","t0":5.625,"t1":9.0803,"beat0":6.75,"beat1":10.896},{"id":"b1","scene":"descent","text":"Underneath, finding where each domain is managed, across a hundred and eighty-nine providers.","t0":10.4167,"t1":16.2286,"beat0":12.5,"beat1":19.474},{"id":"b2","scene":"descent","text":"Signing in to them. O-Auth, Domain Connect, scoped A-P-I keys. A different door at almost every one.","t0":16.875,"t1":23.4893,"beat0":20.25,"beat1":28.187},{"id":"b3","scene":"descent","text":"For the hundred and sixteen with no door, a guided setup that checks every record by itself.","t0":24.1667,"t1":29.7901,"beat0":29,"beat1":35.748},{"id":"b4","scene":"descent","text":"Root domains, which each provider handles its own way.","t0":30.4167,"t1":33.8614,"beat0":36.5,"beat1":40.634},{"id":"b5","scene":"descent","text":"Checking every value until it resolves. Every five seconds at first, with a deadline.","t0":34.375,"t1":39.8267,"beat0":41.25,"beat1":47.792},{"id":"b6","scene":"descent","text":"Certificates, issued on the first visit, and renewed a month before they expire.","t0":40.4167,"t1":46.1861,"beat0":48.5,"beat1":55.423},{"id":"b7","scene":"descent","text":"An edge that gets certificates for every customer's domain, and never for a host it shouldn't.","t0":46.875,"t1":52.3496,"beat0":56.25,"beat1":62.82},{"id":"b8","scene":"descent","text":"And every hour, checking that none of it has drifted.","t0":52.9167,"t1":56.6981,"beat0":63.5,"beat1":68.038},{"id":"c1","scene":"bottom","text":"That's what the button sits on. You could build all of it, and then run it, for as long as you have customers.","t0":57.9167,"t1":63.9626,"beat0":69.5,"beat1":76.755},{"id":"d1","scene":"ascent","text":"Or embed one widget, and leave the ice to us.","t0":65,"t1":68.4985,"beat0":78,"beat1":82.198},{"id":"e1","scene":"end","text":"Custom Domain. You ship the button. We run everything under it.","t0":69.375,"t1":73.8805,"beat0":83.25,"beat1":88.657}];
